import Foundation
import XCTest
@testable import TavliEngine

/// Parity fixtures for the non-Plakoto variants (#137-#139), generated by
/// `ios/scripts/generate_test_fixtures.py --variant <id>` into
/// `Fixtures/fixtures_<id>.json` (gitignored, like the Plakoto fixture).
struct VariantFixtures: Decodable {
    /// A position in the variant's Python-native form: bottom→top stacks
    /// (`plakoto_standard`, `fevga`) or the Portes signed slot array + borne-off counts.
    struct Position: Decodable {
        let points: [[String]]?
        let p: [Int]?
        let off: [Int]?
    }
    struct EncodingCase: Decodable {
        let position: Position
        let is_whites_turn: Bool
        let encoding: [Float]
    }
    struct MoveCase: Decodable {
        let position: Position
        let key: String
        let color: String
        let dice: [Int]
        let moves: [[[Int]]]
        let afters: [String]
        let scores: [Float]?
    }
    struct OutcomeCase: Decodable {
        let position: Position
        let key: String
        let is_over: Bool
        let winner: String?
        let points: Int?
        let value_white: Float?
        let value_black: Float?
    }
    struct NplyCase: Decodable {
        let position: Position
        let color: String
        let dice: [Int]
        let moves: [[[Int]]]
        let scores: [Float]
    }
    struct Nply: Decodable {
        let beam_threshold: Float
        let relative_cutoff: Float?
        let max_branch: Int?
    }

    let variant: String
    let encoder_version: String
    let input_size: Int
    let max_points: Int
    let random_starting_player: Bool
    let has_scores: Bool
    let nply: Nply
    let encoding_cases: [EncodingCase]
    let move_cases: [MoveCase]
    let outcome_cases: [OutcomeCase]
    let nply_cases: [NplyCase]

    static func load(_ variant: String) throws -> VariantFixtures {
        let name = "fixtures_\(variant)"
        let bundle = Bundle.module
        guard let url = bundle.url(forResource: name, withExtension: "json", subdirectory: "Fixtures")
                ?? bundle.url(forResource: name, withExtension: "json") else {
            throw NSError(domain: "Fixtures", code: 1, userInfo: [NSLocalizedDescriptionKey:
                "\(name).json not found — run ios/scripts/generate_test_fixtures.py --variant \(variant)"])
        }
        return try JSONDecoder().decode(VariantFixtures.self, from: Data(contentsOf: url))
    }
}

/// Board for a fixture position under `variant`.
func makeVariantBoard(_ pos: VariantFixtures.Position, variant: any GameVariant) -> GameBoard {
    let board = GameBoard(config: GameConfig(variant: variant))
    if let points = pos.points {
        board.clear()
        for (i, stack) in points.enumerated() { board.setPoint(i, pieces: stack.map(parseColor)) }
    }
    return board
}

/// The canonical position key the generator writes (`_stack_key` / `_portes_key`).
func variantKey(_ board: GameBoard) -> String {
    return board.points.map { pt -> String in
        guard let top = pt.topColor else { return "" }
        return "\(top.rawValue)\(pt.activeCount)\(pt.isCaptured ? "p" : "")"
    }.joined(separator: ",")
}

/// Rules-level parity checks shared by the three variant test classes.
enum VariantParity {
    static func checkMetadata(_ fx: VariantFixtures, _ variant: any GameVariant) {
        XCTAssertEqual(variant.id, fx.variant)
        XCTAssertEqual(variant.makeEncoder(config: GameConfig(variant: variant)).inputSize, fx.input_size)
        XCTAssertEqual(variant.maxPoints, fx.max_points)
        XCTAssertEqual(variant.randomStartingPlayer, fx.random_starting_player)
        XCTAssertEqual(GameVariants.variant(forID: fx.variant)?.id, fx.variant)
    }

    static func checkEncodings(_ fx: VariantFixtures, _ variant: any GameVariant) {
        let encoder = variant.makeEncoder(config: GameConfig(variant: variant))
        var maxDiff: Float = 0
        var worst = -1
        for (i, c) in fx.encoding_cases.enumerated() {
            let enc = encoder.encode(makeVariantBoard(c.position, variant: variant), isWhitesTurn: c.is_whites_turn)
            XCTAssertEqual(enc.count, c.encoding.count, "case \(i) length")
            for k in 0..<min(enc.count, c.encoding.count) where abs(enc[k] - c.encoding[k]) > maxDiff {
                maxDiff = abs(enc[k] - c.encoding[k]); worst = i
            }
        }
        XCTAssertLessThanOrEqual(maxDiff, 1e-6, "max encoding diff \(maxDiff) at case \(worst)")
        print("\(fx.variant) encoding parity: \(fx.encoding_cases.count) cases, maxDiff=\(maxDiff)")
    }

    /// Exact legal-move lists (order included), plus apply → Python's afterstate and
    /// undo → the original position for every move.
    static func checkMoves(_ fx: VariantFixtures, _ variant: any GameVariant) {
        var mismatches = 0, applyMismatches = 0, undoMismatches = 0, moves = 0
        var first = ""
        for c in fx.move_cases {
            let board = makeVariantBoard(c.position, variant: variant)
            XCTAssertEqual(variantKey(board), c.key, "fixture position does not round-trip")
            let dice = Dice()
            dice.set(c.dice[0], c.dice[1])
            let color = parseColor(c.color)
            let got = variant.legalMoves(on: board, color: color, dice: dice)
            if swiftMovePairs(got) != c.moves {
                mismatches += 1
                if first.isEmpty {
                    first = "\(c.key) \(c.color) dice=\(c.dice): want \(c.moves.prefix(6)) got \(swiftMovePairs(got).prefix(6))"
                }
                continue
            }
            for (i, m) in got.enumerated() {
                moves += 1
                variant.apply(m, on: board)
                if variantKey(board) != c.afters[i] { applyMismatches += 1 }
                variant.undo(m, on: board)
                if variantKey(board) != c.key || !board.undoLog.isEmpty { undoMismatches += 1 }
            }
        }
        XCTAssertEqual(mismatches, 0, "\(mismatches)/\(fx.move_cases.count) move-list mismatches. First: \(first)")
        XCTAssertEqual(applyMismatches, 0, "apply afterstate mismatches")
        XCTAssertEqual(undoMismatches, 0, "undo did not restore the position")
        print("\(fx.variant) move parity: \(fx.move_cases.count) cases, \(moves) moves applied/undone")
    }

    static func checkOutcomes(_ fx: VariantFixtures, _ variant: any GameVariant) {
        var over = 0, draws = 0, doubles = 0
        for c in fx.outcome_cases {
            let board = makeVariantBoard(c.position, variant: variant)
            XCTAssertEqual(variant.isOver(on: board), c.is_over, c.key)
            guard c.is_over else { continue }
            over += 1
            let (w, pts) = variant.outcome(on: board)
            XCTAssertEqual(w?.rawValue, c.winner, c.key)
            XCTAssertEqual(pts, c.points, c.key)
            XCTAssertEqual(variant.terminalValue(on: board, perspective: .white), c.value_white!, accuracy: 1e-7, c.key)
            XCTAssertEqual(variant.terminalValue(on: board, perspective: .black), c.value_black!, accuracy: 1e-7, c.key)
            XCTAssertEqual(variant.winner(on: board), w)
            if w == nil { draws += 1 }
            if pts == 2 { doubles += 1 }
        }
        print("\(fx.variant) outcome parity: \(fx.outcome_cases.count) positions, \(over) over, \(draws) draws, \(doubles) 2-point")
    }
}
